class Solution {
public:
    int minimumCost(int n, vector<vector<int>>& highways, int discounts) {
        vector<vector<pair<int, int>>> graph(n);
        for (const auto& edge : highways) {
            graph[edge[0]].push_back({edge[1], edge[2]});
            graph[edge[1]].push_back({edge[0], edge[2]});
        }
        const long long INF = LLONG_MAX / 4;
        vector<vector<long long>> dist(n, vector<long long>(discounts + 1, INF));
        using State = tuple<long long, int, int>;
        priority_queue<State, vector<State>, greater<State>> pq;
        dist[0][0] = 0;
        pq.emplace(0, 0, 0);
        while (!pq.empty()) {
            long long cost = get<0>(pq.top());
            int city = get<1>(pq.top()), used = get<2>(pq.top());
            pq.pop();
            if (cost != dist[city][used]) continue;
            if (city == n - 1) return (int)cost;
            for (auto edge : graph[city]) {
                int next = edge.first, toll = edge.second;
                if (cost + toll < dist[next][used]) {
                    dist[next][used] = cost + toll;
                    pq.emplace(cost + toll, next, used);
                }
                if (used < discounts && cost + toll / 2 < dist[next][used + 1]) {
                    dist[next][used + 1] = cost + toll / 2;
                    pq.emplace(cost + toll / 2, next, used + 1);
                }
            }
        }
        return -1;
    }
};
